export const DEFAULT_CONFIG={version:1,language:'he',world:'metropolis',avatar:{...PRESETS[0]},profile:{name:'Alex Morgan',role:'AI Full Stack Developer',introduction:'I build thoughtful digital products at the intersection of AI and everyday life. From the first prototype to the production release, I turn ambitious ideas into software people love to use.',location:'Remote · Open to collaboration',email:'',website:'',linkedin:'',github:'',languages:'English — fluent\nHebrew — fluent',certifications:'Applied AI & Machine Learning — example course'},skills:[{name:'AI & Machine Learning',items:'Python, LLM APIs, RAG, Embeddings, Model evaluation'},{name:'Full Stack Development',items:'TypeScript, React, Next.js, Node.js, PostgreSQL'},{name:'Shipping & Collaboration',items:'Docker, AWS, CI/CD, Git, Product discovery'}],experience:[{role:'AI Full Stack Developer',company:'Northstar Labs',start:'2023',end:'Present',description:'Built an AI knowledge assistant with grounded answers and source citations.\nDeveloped a React workspace and Python API for reviewing generated outputs.\nIntroduced evaluation datasets and monitoring for model quality.'},{role:'Full Stack Developer',company:'Orbit Studio',start:'2021',end:'2023',description:'Delivered customer dashboards with TypeScript and PostgreSQL.\nWorked with designers to make onboarding simpler and more accessible.\nCreated automated checks and repeatable deployments.'}],education:[{degree:'B.Sc. Computer Science',school:'Example University',start:'2017',end:'2021',description:'Algorithms, distributed systems, databases and machine learning.\nCapstone: a semantic search engine for research papers.'}],projects:[{name:'Atlas',summary:'A team knowledge assistant with semantic search, grounded answers and source citations. Built around retrieval quality and clear access controls.',stack:'Next.js, FastAPI, PostgreSQL',url:''},{name:'CodeLens',summary:'An AI code review workspace that summarizes pull requests and proposes improvements, with developers approving every change.',stack:'TypeScript, GitHub API, LLM evaluation',url:''}],isSample:true};
const LIMIT=12000,hex=/^#[0-9a-f]{6}$/i;
const str=(v,n=LIMIT)=>typeof v==='string'?v.slice(0,n):'';
const pick=(v,values,fallback)=>values.includes(v)?v:fallback;
export function normalizeConfig(input){
 if(!input||typeof input!=='object'||Array.isArray(input))throw Error('This is not a valid portfolio project.');
 if(input.version!==1)throw Error('This project version is not supported.');
 const a=input.avatar||{},p=input.profile||{},base=DEFAULT_CONFIG.avatar;
 const avatar={id:str(a.id,30),skin:hex.test(a.skin)?a.skin:base.skin,hair:pick(a.hair,['crop','curls','bob','bun','none'],base.hair),hairColor:hex.test(a.hairColor)?a.hairColor:base.hairColor,outfit:pick(a.outfit,['hoodie','longsleeve','jacket','tshirt'],base.outfit),top:hex.test(a.top)?a.top:base.top,pants:hex.test(a.pants)?a.pants:base.pants,shoeStyle:pick(a.shoeStyle,['sneakers','boots'],base.shoeStyle),shoes:hex.test(a.shoes)?a.shoes:base.shoes,accessory:pick(a.accessory,['none','glasses','backpack','both'],base.accessory),body:pick(a.body,['slim','regular','athletic'],base.body)};
 avatar.asset=pick(a.asset,['kay-barbarian','kay-knight','kay-mage','kay-rogue','kay-rogue_hooded'],'');
 avatar.model=pick(a.model,['male','female'],['creative','founder'].includes(a.id)?'female':'male');if(avatar.model==='male'&&['hoodie','blazer'].includes(a.outfit))avatar.outfit='longsleeve';if(avatar.model==='female'&&!['hoodie','tshirt'].includes(avatar.outfit))avatar.outfit='tshirt';avatar.face=pick(a.face,['soft','defined'],base.face);avatar.facialHair=pick(a.facialHair,['none','stubble','beard'],'none');avatar.eyeColor=hex.test(a.eyeColor)?a.eyeColor:base.eyeColor;avatar.accessoryColor=hex.test(a.accessoryColor)?a.accessoryColor:base.accessoryColor;avatar.extras=[...new Set((Array.isArray(a.extras)?a.extras:[]).filter(v=>['cap','beanie','headphones','sunglasses','watch','earrings','chain','crossbody'].includes(v)))];if(avatar.extras.includes('cap')&&avatar.extras.includes('beanie'))avatar.extras=avatar.extras.filter(v=>v!=='beanie');
 const profile={};for(const key of Object.keys(DEFAULT_CONFIG.profile))profile[key]=str(p[key],['name','role','location'].includes(key)?120:LIMIT);
 const list=(key,fields)=>(Array.isArray(input[key])?input[key]:[]).slice(0,20).map(row=>Object.fromEntries(fields.map(f=>[f,str(row?.[f])])));
 return {version:1,language:pick(input.language,['he','en'],'he'),world:pick(input.world,WORLDS.map(w=>w.id),'metropolis'),avatar,profile,skills:list('skills',['name','items']),experience:list('experience',['role','company','start','end','description']),education:list('education',['degree','school','start','end','description']),projects:list('projects',['name','summary','stack','url']),isSample:input.isSample===true};
}
export function validateConfig(c){const errors=[];for(const [k,label]of [['name','Your name'],['role','Professional title'],['introduction','Introduction']])if(!c.profile[k].trim())errors.push(`${label} is required.`);for(const [key,field,label]of [['skills','name','skill group'],['experience','role','experience'],['education','degree','education'],['projects','name','project']])c[key].forEach((r,i)=>{if(!r[field].trim())errors.push(`Add a title to ${label} ${i+1}, or remove the empty entry.`)});for(const [label,url]of [['Website',c.profile.website],['LinkedIn',c.profile.linkedin],['GitHub',c.profile.github],...c.projects.map((p,i)=>[`Project ${i+1} link`,p.url])])if(url.trim()&&!safeUrl(url))errors.push(`${label} must be a complete https:// or http:// URL.`);if(c.profile.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.profile.email))errors.push('Enter a valid email address, or leave it blank.');return errors;}
export function safeUrl(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
export const clone=v=>JSON.parse(JSON.stringify(v));
export const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
